sibling_distinctions": [{"other_code": "N_c76629c7b8f64710", "rule": "本节点侧重设计阶段对周边环境的保护要求设定与指标量化；兄弟节点侧重施工及运营期间对周边环境的实际影响评估、监测及保护措施实施。"}, {"other_code": "N_dc4765366246a321", "rule": "本节点侧重确定“控制什么”（指标与等级）；兄弟节点侧重“如何满足”（通过力学分析验证是否满足指标）。"}], "cross_boundary_rule": "涉及设计等级划分、控制指标设定及地质条件对设计参数的影响，主挂载于本节点；涉及基于这些指标进行的具体结构验算或变形预测，主挂载于基坑稳定与变形分析或围护体系。"}]}
